package com.techconsulting.lending.repository; import com.techconsulting.lending.domain.User; import org.springframework.data.jpa.repository.JpaRepository; import java.util.List; import java.util.Optional;
public interface UserRepository extends JpaRepository<User,Long> { Optional<User> findByUsernameIgnoreCase(String username); Optional<User> findByEmailIgnoreCase(String email); Optional<User> findByLenderIdIgnoreCase(String lenderId); List<User> findByEnabledTrueAndEmailPasswordIsNotNullOrderById(); boolean existsByUsernameIgnoreCaseOrEmailIgnoreCase(String username,String email); boolean existsByLenderIdIgnoreCase(String lenderId); }
